function csv(rows,headers){return '\ufeff'+[headers,...rows.map(r=>headers.map(h=>r[h]))].map(row=>row.map(value=>{let v=value??'';if(typeof v==='string'&&/^[=+@]/.test(v))v="'"+v;return '"'+String(v).replaceAll('"','""')+'"'}).join(',')).join('\r\n')}
