function frequencyControls(){return `<div class="segmented" aria-label="Analytical horizon">${FREQUENCIES.map(f=>`<button data-frequency="${f}" class="${f===state.frequency?'active':''}" aria-pressed="${f===state.frequency}">${frequencyLabel(f)}</button>`).join('')}</div>`}
function stat(label,value,caption,ic,featured=false){return `<article class="stat-card ${featured?'featured':''}"><div class="stat-label">${icon(ic)}${label}</div><div class="stat-value">${value}</div><div class="stat-caption">${caption}</div></article>`}
function empty(title,message,ic='activity'){return `<div class="empty-state">${icon(ic)}<h3>${esc(title)}</h3><p>${esc(message)}</p></div>`}
