function table(headers,rows,classes=[]){return `<div class="table-scroll"><table><thead><tr>${headers.map((h,i)=>`<th class="${classes[i]||''}">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>`<td class="${classes[i]||''}">${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
