  const change=(id,key)=>$('#'+id).addEventListener('change',e=>{state[key]=e.target.value;if(key==='dimension')state.hidden.clear();writeURL();renderPlot()});change('dimension','dimension');change('partition','partition');change('dateFrom','from');change('dateTo','to');icons($('#detail'));renderPlot();
