function selectedRows(){if(!current?.series)return[];const s=current.series,codes={training:0,validation:1,test:2};return s.dates.map((d,i)=>i).filter(i=>(state.partition==='all'||s.partition[i]===codes[state.partition])&&(!state.from||s.dates[i]>=state.from)&&(!state.to||s.dates[i]<=state.to))}
